with latest_match as (select s.id, s.customer_id, s.order_date, s.status, s.amount, s.discount, s.shipping_fee, latest.payment_status, latest.payment_method from orders s join lateral (select c.status as payment_status, c.method as payment_method from payments c where c.order_id = s.id and c.paid_at <= s.order_date order by c.paid_at desc, c.id desc limit 1) latest on true), deduped as (select id, order_date, shipping_fee, payment_method from (select *, row_number() over (partition by status order by shipping_fee desc, id) as latest_rank from latest_match) t where latest_rank = 1), filtered as (select *, case when payment_method in ('paypal', 'card') then 'Priority' else 'Other' end as payment_method_group, length(payment_method) as payment_method_length from deduped where order_date >= date '2023-02-27'), with_windows as (select id, payment_method_length, row_number() over (partition by payment_method order by payment_method_length desc, id) as event_seq, sum(payment_method_length) over (order by payment_method_length, id rows between unbounded preceding and current row) as cumulative_payment_method_length, row_number() over (order by shipping_fee, id) as event_seq_2 from filtered), eligible as (select s.* from with_windows s where not exists (select 1 from shipments c where c.order_id = s.id and c.order_id = 27)), kept as (select s.* from eligible s where not exists (select 1 from shipments ch where ch.order_id = s.id and ch.status = 'IN_TRANSIT')), kept_orders as (select s.* from kept s where exists (select 1 from order_items c where c.order_id = s.id and c.quantity between 4 and 6)) select case when event_seq >= 7 then 'PREMIUM' else 'STANDARD' end as event_seq_tier, case when event_seq_2 >= 7 then 'LARGE' else 'SMALL' end as event_seq_2_tier, case when cumulative_payment_method_length >= 335 then 'LARGE' else 'SMALL' end as cumulative_payment_method_length_tier, round(avg(event_seq), 2) as avg_event_seq, approx_percentile(event_seq_2, array(0.25, 0.5, 0.75)) as event_seq_2_quartiles from kept_orders group by case when event_seq >= 7 then 'PREMIUM' else 'STANDARD' end, case when event_seq_2 >= 7 then 'LARGE' else 'SMALL' end, case when cumulative_payment_method_length >= 335 then 'LARGE' else 'SMALL' end
